// Regenerates src/abi.generated.ts from the Foundry artifacts in ../contracts/out.
// Run `forge build` inside ../contracts first. The generated file is committed so the
// front end builds without Foundry installed.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const root = resolve(import.meta.dir, '..', '..', 'contracts', 'out');
const targets = [
  ['seldraFactoryAbi', 'SeldraFactory'],
  ['seldraOrderAbi', 'SeldraOrder'],
] as const;

let out = '// Generated by scripts/sync-abi.ts from the Foundry artifacts. Do not edit by hand.\n\n';
for (const [exportName, contract] of targets) {
  const artifact = JSON.parse(readFileSync(resolve(root, `${contract}.sol`, `${contract}.json`), 'utf8')) as {
    abi: unknown[];
  };
  out += `export const ${exportName} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n\n`;
}
writeFileSync(resolve(import.meta.dir, '..', 'src', 'abi.generated.ts'), out);
console.log('abi.generated.ts written');
